import{_ as r,l,o as e,c as s,v as t,p as n,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"域分解法","description":"","frontmatter":{"title":"域分解法","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/domain-decomposition-mask.md","filePath":"litho/domain-decomposition-mask.md","lastUpdated":1789023840000}'),E={name:"litho/domain-decomposition-mask.md"};function m(c,a,A,_,u,D){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="域分解掩模电磁" tabindex="-1">域分解掩模电磁 <a class="header-anchor" href="#域分解掩模电磁" aria-label="Permalink to &quot;域分解掩模电磁&quot;">​</a></h1><div class="epigraph"><p>全场麦克斯韦不可算；把掩模切成重叠域，近场拼接，用严格解去伺候 OPC 真正在乎的那一圈边。</p><footer>—— 对照掩模 EMF 域分解 / 重叠近场拼接的计算光刻公开方法</footer></div><p><a href="/litho/rcwa">上一课</a>把周期结构交给模态法。缺口是逻辑版既非无限周期也不可整场 FDTD。本课钉域分解。严格近场如何变成可校准的胶模型，留给[下一课](/litho/resist-model-calibration）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OPC 要的是局部空中像对碎片的灵敏度。掩模 3D 的电磁相关长度通常比设计规则短：离边几个波长外，场接近「局部环境 + 周期近似」。域分解：把版切成带重叠的窗口，每个窗口 FDTD 或 RCWA 超胞，再把近场在重叠区混合，避免缝上的假衍射。Adam–Neureuther 一类工作与后续 EDA 实现走这条工程路。</p><p>缺口是<strong>可拼的严格性</strong>，不是发明一种新麦克斯韦。把域分解当「免费全芯片 FDTD」，重叠与窗宽选错会在缝上造热点。</p><h3 id="窗宽是物理不是软件参数" tabindex="-1">窗宽是物理不是软件参数 <a class="header-anchor" href="#窗宽是物理不是软件参数" aria-label="Permalink to &quot;窗宽是物理不是软件参数&quot;">​</a></h3><p>窗必须覆盖电磁相关长度与助条邻域，否则边界条件（周期、PML）污染中心像素。窗太大则回到算力墙。这与光学 TCC 的核半径不同：一个是掩模近场，一个是投影成像。</p><p><span class="marginnote">分解是空间上的；与 SMO 的光瞳分解不是一件事。不要把「decomposition」在双重图形着色课里的词义混进来——那是后课着色。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：按图形密度或规则网格切窗 → 每窗严格 EMF → 重叠加权拼接 → 远场成像或生成局部边界条件给紧凑核。热区窗加密、稀疏区用薄屏。与 GPU：窗独立，可并行，但仍不是全芯片每迭代全严格。</p><p>验证：与大窗 FDTD 参考比中心 CD；缝上 EPE 必须低于预算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>麦克斯韦是局域微分方程，信息以有限速度（数值上以网格）传播；稳态频域里是倏逝衰减长度。超过衰减长度，远处几何对本地近场的贡献可忽略，于是分解合法。金属波导般的异常结构可以让相关长度变长，窗宽经验必须覆盖这类图形，不能只按介质石英估。</p>',14)),(e(),n(h,null,{default:o(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHIP%5B%22%E5%85%A8%E8%8A%AF%E7%89%87%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20WIN%5B%22%E9%87%8D%E5%8F%A0%E7%AA%97%22%5D%0A%20%20WIN%20--%3E%20EMF%5B%22%E7%AA%97%E5%86%85%20FDTD%20%2F%20RCWA%22%5D%0A%20%20EMF%20--%3E%20JOIN%5B%22%E8%BF%91%E5%9C%BA%E6%8B%BC%E6%8E%A5%22%5D%0A%20%20JOIN%20--%3E%20IMG%5B%22%E6%88%90%E5%83%8F%20%2F%20%E7%B4%A7%E5%87%91%E6%A0%B8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>域分解不消除材料 \\(n,k\\) 误差，不替代 AIMS 对修复材料。缝伪影是方法风险，必须有监测。不把某 EDA 模块名当算法定义。</p><p>后课默认：严格 EMF 可以按窗提供教师数据；下一课用这些（外加晶圆 FEM）去校准紧凑胶模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>域分解用重叠窗把严格掩模 EMF 接到可算尺度。</li><li>窗宽由电磁相关长度决定；缝必须验证。</li><li>仍不能每步全芯片严格，只给紧凑核与热区当老师。</li><li>出处：掩模 EMF 域分解的计算光刻公开方法（Adam–Neureuther 传统及后续工程实现）。</li></ul>',5))])}const F=r(E,[["render",m]]);export{T as __pageData,F as default};
